import * as fs from 'node:fs/promises';
const c = JSON.parse(await fs.readFile(Bun.argv[2], 'utf8')); const j = async p => JSON.parse(await fs.readFile(p, 'utf8')); const a = await j(c.evidence + '/assessment.json'), t = await j(c.evidence + '/result-template.json'), l = await j(c.evidence + '/launch-session.json');
async function cmd(argv, cwd = c.worktree) { const p = Bun.spawn(argv, { cwd, stdout: 'pipe', stderr: 'pipe' }); const [stdout, stderr, code] = await Promise.all([new Response(p.stdout).text(), new Response(p.stderr).text(), p.exited]); if (code) throw Error(stderr); return stdout.trim(); }
const tuple = (await cmd(['git', 'rev-parse', 'HEAD', 'HEAD^{tree}'])).split('\n'); if (tuple[0] !== c.commit || tuple[1] !== c.tree || await cmd(['git', 'status', '--porcelain'])) throw Error('Frozen source changed or dirty'); if (a.assessment_complete !== true || a.code_inspection_complete !== true || !['SUCCESS', 'FAILURE'].includes(a.verdict) || !Array.isArray(a.findings) || JSON.stringify([...a.reviewed_files].sort()) !== JSON.stringify([...c.files].sort())) throw Error('Complete exact-scope assessment missing'); if (a.verdict === 'SUCCESS' && a.findings.some(f => f.blocking !== false)) throw Error('Blocking findings cannot produce SUCCESS'); if (c.role === 'standards' && a.standards_assessment_complete !== true || c.role === 'spec' && a.spec_assessment_complete !== true) throw Error('Assigned independent axis incomplete');
const doc = JSON.parse(await cmd(['mise', 'exec', '--', 'mq', '--allow-http-import', '-I', 'raw', '-F', 'json', 'import "github.com/harehare/okf.mq" | let d = okf::okf_parse(.) | {fields:d["frontmatter"],body:d["body"]}', c.artifact], c.root)); if (doc.fields.reviewed_commit !== c.commit || doc.fields.reviewed_tree !== c.tree || doc.fields.verdict !== a.verdict || doc.fields.review_role !== c.role || !doc.body.includes(c.commit) || !doc.body.includes(t.ticket_ref) || c.files.some(p => !doc.body.includes(p))) throw Error('Sole immutable review artifact omits actual identity/scope'); if (c.role === 'standards' && c.smells.some(name => !doc.body.includes(name))) throw Error('All12smell heuristics must be assessed, not omitted');
const result = { ...t, created_at: new Date().toISOString(), session_id: l.session_id, pane_id: l.pane_id, status: a.verdict === 'SUCCESS' ? 'completed' : 'failed', verdict: a.verdict, findings: a.findings, summary: a.summary, assessment_complete: true, code_inspection_complete: true, valid_source_verdict: true, standards_assessment_complete: a.standards_assessment_complete === true, spec_assessment_complete: a.spec_assessment_complete === true, scope: { fixed_point: c.base, source_commit: c.commit, source_tree: c.tree, reviewed_files: c.files, all_changed_paths_reviewed: true }, validation: [{ command: 'Recorded full Bun suite and scoped compiler', result: '152pass0fail2145assertions13files;compiler0', evidence_ref: c.checksRef }, { command: 'Actual offline production Pi queue matrix on exact source', result: '35passedobservations24framescolour+mono40x12/80x24/120x40;cleanup0', evidence_ref: c.nativeRef }], review_artifact: c.artifactRef, source_dirty: false, source_committed: true, limitations: ['This independent role assesses only its named axis; a separate fresh main review must inspect both axes before finish.', 'SVG fallback does not establish exact glyph/colour pixel fidelity.'], outputs: [...t.outputs, { kind: 'review', ref: c.artifactRef }], inputs: [...t.inputs, { kind: 'evidence', ref: c.evidenceRef + '/assessment.json' }] }; await fs.writeFile(c.workflow + '/events/' + c.result + '.json', JSON.stringify(result, null, 2) + '\n', { flag: 'wx' }); console.log(JSON.stringify({ receipt: c.result, verdict: result.verdict, source_commit: c.commit, artifact: c.artifactRef, blocking_findings: a.findings.filter(f => f.blocking !== false).length }));
